<?php
/** Eight original Yangon guides scheduled for 2026-08-31 through 2026-09-07. */
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

function livingtmw_september_evidence_footer( string $scope, array $sources ): string {
	$html = '<div class="livingtmw-field-note"><strong>취재·경험 범위</strong> ' . esc_html( $scope ) . ' 가격과 제도는 달라질 수 있으므로 중요한 결정 전 담당 기관에 다시 확인하세요.</div><div class="livingtmw-field-sources"><h2>확인 자료와 날짜</h2><ul>';
	foreach ( $sources as $label => $url ) {
		$html .= '<li><a href="' . esc_url( $url ) . '" target="_blank" rel="noopener noreferrer">' . esc_html( $label ) . '</a> <span>(확인: 2026-08-29)</span></li>';
	}
	return $html . '</ul></div>';
}

function livingtmw_september_guide_image( string $file, string $alt ): string {
	return livingtmw_article_image( $file, $alt );
}

/** Match each scheduled guide with the image shown in its search/social metadata. */
function livingtmw_september_guide_image_file( string $slug ): string {
	$images = array(
		'yangon-ybs-bus-route-fare-guide'          => 'yangon-ybs-bus-guide.png',
		'inno-city-yangon-water-bill'               => 'yangon-water-bill-guide.png',
		'myanmar-form-c-condo-registration'         => 'myanmar-form-c-guide.png',
		'yangon-apartment-bcc-building-permit'      => 'yangon-bcc-apartment-guide.png',
		'yangon-dengue-monsoon-family-checklist'    => 'yangon-dengue-prevention.png',
		'yangon-diarrhea-cholera-food-water-safety' => 'yangon-food-water-safety.png',
		'myanmar-mobile-payment-cash-security'      => 'myanmar-mobile-payment-security.png',
		'myanmar-korean-resident-safety-plan'       => 'myanmar-korean-safety-plan.png',
	);
	return $images[ $slug ] ?? '';
}

function livingtmw_september_depth( string $slug ): string {
	$sections = array(
		'yangon-ybs-bus-route-fare-guide' => '<section><h2>회사와 함께 만들 수 있는 현실적인 출퇴근 기록</h2><p>직원이 지각한 날에는 단순히 늦었다고 끝내지 말고 평소 정류장 도착시각, 기다린 시간, 사라진 노선번호, 대체차량을 탄 시각과 최종 도착시각을 사실대로 남기는 편이 좋습니다. 같은 일이 반복되면 개인의 준비 부족인지 실제 노선변동인지 구분할 근거가 생깁니다. 회사도 출근시간만 지적하기보다 같은 지역에서 오는 직원들의 기록을 모아 통근버스, 합승차량, 유연 출근이나 비상 택시비 지원 중 어떤 대안이 효율적인지 판단할 수 있습니다.</p><p>새 직원을 채용할 때는 집과 회사의 지도상 거리만 보지 말고 실제 교통수단과 첫차·막차, 환승횟수를 묻습니다. 우기에는 정류장까지 걷는 길의 침수와 비를 피할 장소도 중요합니다. 운전기사가 있는 회사라도 모든 직원이 그 차량을 이용할 수 있는 것은 아니므로 직급이나 고용형태에 따라 안전한 이동 선택지가 달라지지 않는지 살펴야 합니다.</p><h2>고장이나 사고 상황에서는 사실만 기록합니다</h2><p>버스가 멈추면 차량번호를 촬영하려고 차도에 서거나 기사와 다투지 않습니다. 먼저 보도나 안전한 장소로 이동하고 회사에 현재 위치와 예상 지연을 알립니다. 연기나 화재 위험이 있으면 차량에서 거리를 두고 현지 긴급안내를 따릅니다. 온라인에 올릴 때도 정비상태를 검사하지 않은 사람이 특정 회사의 불법운행이라고 단정하지 말고, 본 시각·장소·외관과 실제로 발생한 지연만 구분해 적습니다.</p></section>',
		'inno-city-yangon-water-bill' => '<section><h2>우리 집 사용량을 생활행동과 연결해 봅니다</h2><p>월말 숫자만 보면 왜 12.2톤이 나왔는지 설명하기 어렵습니다. 샤워와 세탁을 억지로 세지 않아도 장기손님 방문, 여행으로 집을 비운 날, 침구 대량세탁, 물탱크 청소와 누수수리처럼 사용량을 크게 바꾸는 사건은 달력에 남길 수 있습니다. 다음 달 사용량이 갑자기 두 배가 되면 이 기록을 검침오류나 누수 가능성과 비교합니다.</p><p>세대 미터와 관리실 청구서의 단위가 다르면 환산식을 서면으로 요청합니다. 1톤이 일반적으로 물 1세제곱미터와 대응하더라도 해당 건물의 유닛이 같은 의미인지 임의로 가정하지 않습니다. 검침 숫자의 소수점 위치, 미터 교체일과 계량기 번호도 사진에서 확인합니다. 미터가 교체되면 이전 기기의 마지막값과 새 기기의 시작값을 같은 날 기록해야 사용량 공백을 막을 수 있습니다.</p><h2>집주인과 세입자의 부담을 계약서에 적습니다</h2><p>정상 사용분은 세입자가 내더라도 노후배관 누수, 공용탱크 문제와 미터 고장 비용은 책임주체가 다를 수 있습니다. 계약 전에 수도요금 납부일, 연체료, 보증금 공제조건과 대규모 수리 책임을 정합니다. 이사하는 날에는 마지막 검침사진과 납부영수증을 집주인에게 보내 미납 분쟁을 예방합니다.</p></section>',
		'myanmar-form-c-condo-registration' => '<section><h2>주소 표기를 하나로 통일합니다</h2><p>양곤 주소는 콘도명, Ward, 타운십과 도로명의 영문 표기가 서류마다 조금씩 달라질 수 있습니다. 임대계약서, Form C 관련 제출자료, 회사 인사기록과 은행 주소가 서로 다른 장소처럼 보이지 않게 관리실에서 사용하는 공식 영문표기를 받아 둡니다. 동·층·호수와 집주인 이름도 대조합니다. 철자 차이가 있다면 임의로 고치기보다 담당자에게 어느 표기를 써야 하는지 확인합니다.</p><p>담당직원에게 맡길 때는 여권 사본 전송 메시지에 사용목적을 적고 불필요한 페이지를 보내지 않습니다. 접수 완료 뒤에는 증빙을 PDF나 사진으로 받아 파일명에 입국일과 주소를 넣습니다. 가족 여러 명을 함께 처리했다면 사람별로 모두 등록됐는지 확인합니다. 한 사람의 증빙을 가족 전체의 완료증명으로 오해하지 않습니다.</p><h2>문제가 생겼을 때 설명할 시간순서를 만듭니다</h2><p>입국일, 실제 입주일, 직원에게 서류를 준 날, 접수일과 완료일을 한 줄로 정리합니다. 지연이 있었다면 담당자에게 재촉한 메시지와 답변을 보관합니다. 이는 위반을 자동으로 없애는 자료가 아니라 거주자가 언제 무엇을 했는지 정확히 설명하는 기록입니다. 주소가 잘못됐거나 신고가 누락됐다는 사실을 알게 되면 온라인 경험담으로 해결책을 추측하지 말고 관할 기관에 정정 절차와 필요한 서류를 문의합니다.</p></section>',
		'yangon-apartment-bcc-building-permit' => '<section><h2>가격이 싸다는 이유를 문서로 설명할 수 있어야 합니다</h2><p>주변 시세보다 크게 저렴한 물건에는 급매, 내부수리 필요, 임대차 승계처럼 설명 가능한 이유가 있을 수 있지만 허가·권리 문제도 숨어 있을 수 있습니다. 판매자 말만 듣지 말고 같은 건물의 최근 거래, 관리비 체납, 공용시설 수리와 소송·행정조치 여부를 확인합니다. 싸게 샀다는 기쁨보다 최악의 경우 되팔거나 임대할 수 있는지를 먼저 계산합니다.</p><p>운영자는 양곤 주택 매도가 오래 걸린 경험을 기존 글에 공개했습니다. 매수할 때의 서류 문제는 나중에 매도 유동성을 더 낮출 수 있습니다. 구매 당시에는 거주만 하면 된다고 생각해도 귀국, 회사 이동과 가족상황 때문에 처분해야 할 수 있으므로 미래 매수자가 요구할 문서까지 준비된 물건인지 봅니다.</p><h2>확인 결과를 계약조건으로 옮깁니다</h2><p>전문가 검토가 끝났다는 말로 만족하지 말고 확인된 문서 목록을 계약서 부속자료로 붙입니다. 매도인의 진술이 거짓이거나 행정조치 때문에 이전·거주가 불가능해질 때 계약해제, 환불, 손해와 비용부담을 어떻게 처리할지 적습니다. 한국어 번역만 읽지 말고 실제 효력이 있는 언어의 계약서와 번역이 같은지 검토합니다. 이해하지 못한 조항에는 현장에서 바로 서명하지 않습니다.</p></section>',
		'yangon-dengue-monsoon-family-checklist' => '<section><h2>상비약 상자를 뎅기열 기준으로 다시 봅니다</h2><p>제품 앞면의 감기, 몸살 문구보다 뒷면의 성분명과 함량을 확인합니다. 가족이 복용하는 해열진통제, 종합감기약과 처방약을 표로 만들면 같은 성분의 중복과 뎅기열 의심 때 피해야 할 약을 의료진에게 설명하기 쉽습니다. 아이 약은 최근 체중에 맞는 계량도구와 함께 보관하고 유효기간이 지난 제품은 현지 폐기안내에 따라 처리합니다.</p><p>열이 시작되면 모기장을 환자에게도 사용해 다른 모기가 환자를 물고 주변 사람에게 바이러스를 옮길 가능성을 줄입니다. 환자가 낮에 쉬는 공간의 방충망과 모기 노출을 점검합니다. 가족이 번갈아 돌볼 때 체온과 수분섭취 기록을 하나로 공유하면 약을 중복해 주거나 경고증상을 놓치는 일을 줄일 수 있습니다.</p><h2>방역 뒤에도 발생원을 없애야 합니다</h2><p>연무소독이나 모기약은 눈앞의 성충을 줄일 수 있지만 화분받침, 배수구와 저장통의 알·유충 관리까지 자동으로 해결하지 않습니다. 약품 냄새가 강할 때는 아이와 반려동물을 안전하게 이동시키고 관리실 안내에 따라 환기합니다. 이웃집과 공용구역에서 물고임이 반복되면 개인 집 안만 관리하지 말고 사진과 날짜를 모아 공동 점검을 요청합니다.</p></section>',
		'yangon-diarrhea-cholera-food-water-safety' => '<section><h2>가족이 아플 때 같은 음식을 계속 먹지 않습니다</h2><p>한 사람이 설사를 시작하면 남은 음식과 물을 바로 다른 가족에게 제공하지 않습니다. 가능하면 용기를 밀봉해 조리시간, 구입처와 먹은 사람을 표시하고 의료진이나 보건당국이 필요로 하는지 확인합니다. 사용한 화장실, 손잡이와 조리공간은 제품 지침에 맞는 방법으로 청소하고 환자의 수건과 식기를 깨끗하게 관리합니다. 손 씻기는 장갑 사용을 대신하지 않습니다.</p><p>회복 중에는 탈수상태와 의료진 안내에 맞춰 음식을 선택합니다. 매운 음식이나 기름진 음식이 무조건 금지된다고 일반화하기보다 환자가 물과 음식을 유지할 수 있는지, 구토가 반복되는지 관찰합니다. 아이에게 성인용 지사제나 남은 항생제를 나눠 주지 않습니다.</p><h2>다시 갈 식당은 문제 대응까지 기록합니다</h2><p>맛과 가격뿐 아니라 뜨거운 음식의 온도, 얼음·식수 설명, 포장상태와 문의 대응을 기록합니다. 배달음식은 도착시각과 누수·밀봉 상태를 사진으로 남기고 바로 먹지 않으면 신속히 냉장합니다. 문제가 생겼을 때 식당이 환불했는지만 보지 말고 원인을 확인하고 같은 실수를 줄이려 했는지를 봅니다. 한 번의 증상만으로 비난하지 않되 반복되는 위생문제를 무시하지도 않는 균형이 필요합니다.</p></section>',
		'myanmar-mobile-payment-cash-security' => '<section><h2>주간 결산은 10분이면 충분합니다</h2><p>고정한 요일에 KBZPay, 은행계좌와 지갑의 현금을 함께 확인합니다. 잔액만 맞추지 말고 수취인 이름이 낯선 거래, 같은 금액의 중복결제, 취소했는데 돌아오지 않은 금액과 예상하지 않은 수수료를 찾습니다. 식비·교통·공과금처럼 간단한 범주를 붙이면 생활비 기록도 동시에 됩니다. 이상거래가 보이면 거래번호, 시각과 화면을 저장하고 공식 고객센터에 즉시 문의합니다.</p><p>가게에서 개인 직원 계정으로 보내 달라는 경우 매장 결제인지 개인송금인지 확인하고 영수증을 받습니다. 수취인 이름이 다르면 이유를 묻고 확인 전에는 보내지 않습니다. 잘못 보낸 뒤 상대방에게 추가 송금해야 돌려준다는 요구를 받으면 혼자 해결하지 말고 금융사 절차를 따릅니다.</p><h2>가족의 복구 절차를 시험합니다</h2><p>본인이 연락할 수 없을 때 가족이 어떤 은행과 모바일지갑을 쓰는지 알되 PIN과 OTP를 공유하지는 않습니다. 분실신고 전화번호, 계정명의와 필요한 신분서류 위치만 안전하게 남깁니다. 새 전화나 SIM으로 바꿀 때는 공식 대리점과 은행을 이용하고, 중고기기를 처분하기 전 금융앱 로그아웃, 기기연결 해제와 초기화를 순서대로 진행합니다.</p></section>',
		'myanmar-korean-resident-safety-plan' => '<section><h2>가족회의에서는 역할을 사람 이름으로 정합니다</h2><p>재난이 나면 누군가 연락하겠지라고 생각하지 말고 아이를 데려올 사람, 반려동물과 약을 챙길 사람, 회사와 대사관에 연락할 사람을 정합니다. 한 사람이 출국하거나 출장 중일 때 대신할 사람도 둡니다. 집 밖 가까운 집결지와 동네를 벗어난 두 번째 장소를 정하고 통화가 안 될 때 보낼 짧은 문자 형식을 맞춥니다.</p><p>차량을 쓰는 가족은 등록증 원본을 안전하게 보관하고 휴대해야 하는 서류의 적법한 사본 형태를 확인합니다. 차량번호, 보험, 긴급출동과 정비소 연락처를 전화 밖에도 둡니다. 운전기사가 있다면 사고와 검문 때 누구에게 먼저 연락하고 어떤 문서에 임의로 서명하지 말아야 하는지 함께 교육합니다.</p><h2>들은 이야기는 행동 전에 공식 확인합니다</h2><p>교민사회 경험은 빠른 단서가 되지만 벌금, 비자, 보험과 법률문제의 최종 근거가 될 수 없습니다. 누가 언제 어떤 조건에서 겪었는지 확인하고 현재 공식기관 답변과 대조합니다. 운영자가 들은 하루 3달러 이야기도 이런 원칙 때문에 본문의 기준으로 사용하지 않았습니다. 편리한 답보다 위험을 줄이는 답을 선택하고, 확인한 날짜와 담당기관을 기록하는 것이 장기거주자의 중요한 생활기술입니다.</p></section>',
	);
	return ( $sections[ $slug ] ?? '' ) . livingtmw_september_final_notes( $slug );
}

function livingtmw_september_final_notes( string $slug ): string {
	$notes = array(
		'yangon-ybs-bus-route-fare-guide' => '<section><h2>첫 한 달은 통근 실험 기간으로 잡습니다</h2><p>입사 첫날 정한 노선을 계속 고집하기보다 4주 동안 출발시각과 도착시각을 요일별로 적어 봅니다. 월요일 정체와 비 오는 날의 대기시간은 평소와 다를 수 있으므로 같은 조건끼리 비교해야 합니다. 지각이 반복되면 직원 개인의 성실성만 문제 삼기 전에 노선이 실제로 유지되는지, 환승 지점에서 마지막 연결편을 놓치는지, 택시로 전환할 수 있는 지점이 어디인지 함께 확인합니다. 회사는 한 사람의 기록이 아니라 같은 지역 직원 여러 명의 기록을 모아 통근버스나 합승 지원이 필요한지 판단할 수 있습니다.</p><p>비상 교통비는 매일 쓰는 돈이 아니라 버스가 오지 않거나 차량 상태가 불안할 때 이동을 중단할 수 있게 해 주는 선택권입니다. 직원에게도 고장 난 차를 억지로 타기보다 안전한 곳에서 내리고 담당자에게 현재 위치를 알리는 기준을 미리 설명해 둡니다. 노선번호, 정류장 이름, 대체 이동수단과 회사 연락처를 작은 메모로 저장하면 데이터가 끊겨도 대응하기 쉽습니다.</p></section>',
		'inno-city-yangon-water-bill' => '<section><h2>청구액이 다르면 숫자부터 같은 기준으로 맞춥니다</h2><p>이의를 제기하기 전 이번 달과 지난달 계량기 사진, 촬영 날짜, 고지서의 이전 검침값과 현재 검침값을 한 화면에 정리합니다. Inno City에서 운영자가 확인한 1톤당 1,800짯과 2026년 7월 12.2톤은 한 세대의 실제 기록이지 모든 단지에 적용되는 공공요금표가 아닙니다. 따라서 다른 콘도와 비교할 때는 수도 원가뿐 아니라 공용탱크 관리비, 펌프 전기료, 고정비가 별도로 붙는지 먼저 물어야 합니다. 12.2에 1,800을 곱한 21,960짯은 단순 사용료 계산값이며 실제 고지액과 같다고 단정하지 않습니다.</p><p>관리사무소에는 말로만 문의하지 않고 세대번호, 고지월, 검침값과 질문을 짧게 적어 보냅니다. 답변을 받으면 담당자 이름과 날짜를 남기고 다음 달 고지서에서 수정 여부를 확인합니다. 누수 의심 때는 집 안의 모든 수도를 잠근 뒤 계량기가 계속 움직이는지 관찰하되, 밸브나 공용배관을 임의로 분해하지 않습니다. 이사 전 마지막 검침 사진과 납부 영수증을 집주인과 동시에 공유하면 퇴거 뒤 생길 수 있는 미납 분쟁도 줄일 수 있습니다.</p></section>',
		'myanmar-form-c-condo-registration' => '<section><h2>이사 날짜를 기준으로 서류 담당을 다시 확인합니다</h2><p>운영자는 담당직원에게 처리를 맡겼기 때문에 직접 방문 창구나 소요시간을 경험한 것처럼 쓰지 않습니다. 대신 입주 전 집주인 또는 관리사무소에 외국인 거주 신고를 누가 맡는지, 여권 원본이 필요한지, 접수 뒤 어떤 증빙을 주는지를 문장으로 확인합니다. 거주지역 관할에서 처리하는 것으로 알고 있었더라도 주소와 체류자격에 따라 절차가 달라질 수 있으므로 예전 경험만으로 날짜를 정하지 않습니다. 호텔에서 콘도로 옮기거나 다른 타운십으로 이사할 때에는 이전 주소 기록과 새 계약서의 표기가 일치하는지도 봅니다.</p><p>회사 직원이 대신 움직일 경우 전달한 서류 목록과 반환받은 날짜를 체크합니다. 여권을 맡겨야 한다면 수령자와 보관 목적을 확인하고 필요 이상 오래 두지 않습니다. 접수가 늦어졌다는 말을 들으면 벌금을 추측해 바로 지불하기보다 관할기관, 집주인, 필요하면 대사관 안내를 차례로 확인합니다. 출국 때 하루 3달러라는 주변 이야기는 시점과 상황이 확인되지 않은 전언이므로 체류 연장의 대안으로 계산해서는 안 됩니다. 가장 안전한 비용 절감법은 만료일 전에 공식 절차를 확인하는 것입니다.</p></section>',
		'yangon-apartment-bcc-building-permit' => '<section><h2>문서가 연결되지 않으면 계약을 멈추는 기준을 세웁니다</h2><p>BCC라는 이름을 들었다는 사실만으로 건물 전체와 내가 살 호실의 권리가 확인되는 것은 아닙니다. 허가 문서의 주소, 건물명, 층수와 용도가 현장 및 계약서와 이어지는지 전문가에게 확인하고, 사본을 받은 날짜와 제공자를 기록합니다. 증축된 층이나 분할된 호실이라면 원래 승인 범위에 포함되는지 별도로 묻습니다. 운영자가 강조하는 핵심은 특정 기관이 아무 이유 없이 집을 빼앗는다고 단정하는 것이 아니라, 허가와 권리관계가 불분명한 매매에서 행정조치나 사용 제한이 생기면 투자금을 회수하기 매우 어려울 수 있다는 점입니다.</p><p>중개인이 오늘 계약금이 필요하다고 재촉하거나 원본은 나중에 보여 주겠다고 하면 가격 협상보다 검증을 우선합니다. 확인되지 않은 문서를 조건으로 계약금을 보낼 때에는 환불 조건과 기한이 계약서에 명확한지 법률전문가에게 검토받습니다. 현장에서는 계량기, 비상계단, 소방 접근로와 실제 호실번호도 사진으로 남깁니다. 매도인 이름, 등기 또는 권리서류, 세금과 관리비 납부기록이 서로 맞지 않으면 이유가 해소될 때까지 서명과 송금을 멈추는 것이 운영자의 매수 중단 기준입니다.</p></section>',
		'yangon-dengue-monsoon-family-checklist' => '<section><h2>가족과 직원에게 같은 발열 기준을 공유합니다</h2><p>감기 기운이 있을 때 상비약을 먼저 찾는 운영자의 습관은 편리하지만, 양곤 우기에는 열의 원인을 스스로 확정하지 않는 규칙도 필요합니다. 체온을 잰 시각, 복용한 약의 제품명과 성분, 물을 마신 양과 동반 증상을 적어 두면 진료 때 설명하기 쉽습니다. 특히 기존 감기약과 해열제를 함께 먹을 때 같은 성분이 겹칠 수 있으므로 포장을 보관하고 약사나 의료진에게 확인합니다. WHO가 안내하는 경고증상이나 상태 악화가 보이면 평소 감기와 비슷하다는 이유로 기다리지 않습니다.</p><p>집, 사무실, 직원 숙소는 금요일처럼 고정된 날에 화분받침, 양동이, 배수구 주변과 옥상 용기를 함께 확인합니다. 물을 버리는 사람과 방충망을 살피는 사람을 정해 두면 모두가 하겠지 하고 넘기는 일을 줄일 수 있습니다. 아이나 고령자가 있는 집은 자주 가는 병원의 야간 연락방법과 이동차량을 미리 적어 둡니다. 뎅기열을 직접 겪지 않았다는 운영자의 경험 범위를 밝히고, 예방 행동과 의료 판단은 최신 WHO 및 현지 의료기관 안내를 기준으로 삼습니다.</p></section>',
		'yangon-diarrhea-cholera-food-water-safety' => '<section><h2>48시간 기록이 다음 선택을 바꿉니다</h2><p>설사가 생기면 마지막 한 끼만 원인으로 지목하기 쉽지만 섭취 시점과 증상 시작에는 간격이 있을 수 있습니다. 운영자는 최근 48시간 동안 먹은 장소, 함께 먹은 사람, 물과 얼음, 증상 시작시각과 횟수를 메모합니다. 음식 냄새를 맡고 주방 쪽을 보는 습관은 명백한 이상을 피하는 데 도움을 줄 수 있지만 냄새가 정상이라고 병원체가 없다는 뜻은 아닙니다. 손 씻기, 충분히 익힌 음식, 안전하게 밀봉된 물과 깨끗한 보관온도를 함께 확인해야 합니다.</p><p>가족용 준비가방에는 의료기관 연락처, 신분증 사본, 복용약 목록과 깨끗한 물을 두되 치료제는 의료진의 지시에 따릅니다. 소변량 감소, 심한 무기력, 계속되는 구토처럼 탈수가 의심되거나 혈변과 고열이 있으면 기록만 계속하지 말고 진료를 받습니다. 같은 식당을 이용한 여러 사람이 아팠다면 영수증과 주문내역을 보관하고 관리주체 또는 보건기관에 사실 중심으로 알립니다. 한 번의 경험을 특정 식당 전체의 위생 수준으로 일반화하지 않는 것도 정확한 생활정보를 만드는 원칙입니다.</p></section>',
		'myanmar-mobile-payment-cash-security' => '<section><h2>한 달에 한 번 계정 복구까지 점검합니다</h2><p>운영자는 KBZPay를 자주 쓰며 현재까지 접속 문제를 겪지 않았지만, 개인 경험이 서비스 전체의 안정성을 보장하지는 않습니다. 3~4일마다 앱을 볼 때 잔액만 확인하지 않고 등록 전화번호, 연결된 기기, 최근 거래와 알림 수신 여부를 함께 봅니다. 현금을 많이 쓰는 생활에서는 앱 기록과 실제 현금지출이 분리되므로 큰 금액을 인출한 날짜와 사용 목적도 간단히 적어야 월말 차이를 찾기 쉽습니다. 결제 화면을 다른 사람에게 보여 줄 때 잔액과 개인정보가 노출되지 않도록 주의합니다.</p><p>매달 한 번은 휴대전화를 잃어버렸다고 가정해 통신사, 은행과 지갑 서비스의 공식 연락처를 최신 상태로 저장합니다. 비밀번호 재설정에 필요한 신분확인 수단은 안전한 장소에 두고, OTP와 PIN 자체를 가족이나 직원에게 전달하지 않습니다. 링크를 누르거나 화면공유 앱을 설치하라는 연락은 상대가 아는 사람처럼 보여도 끊은 뒤 공식 채널로 다시 확인합니다. 장애가 생기면 여러 번 송금 버튼을 누르기보다 거래번호와 상태를 먼저 확인해 중복 결제를 예방합니다.</p></section>',
		'myanmar-korean-resident-safety-plan' => '<section><h2>분기마다 가족 비상연락 연습을 합니다</h2><p>연락망은 저장해 두는 것보다 실제로 연결되는지 확인하는 일이 중요합니다. 석 달에 한 번 가족이 각자 대사관, 현지 병원, 집주인 또는 관리사무소와 회사 담당자의 번호를 확인하고, 한 사람이 연락되지 않을 때 다음 순서를 연습합니다. 여권과 비자 만료일은 가족 캘린더에 두 번 알림을 설정하고 원본 위치와 암호화된 사본의 접근방법을 성인 가족끼리 공유합니다. 어린이에게는 긴 설명 대신 보호자 이름, 전화번호와 만날 장소를 알려 줍니다.</p><p>출국 일정이 가까우면 주변의 벌금 경험담보다 본인의 체류도장과 공식 안내를 먼저 확인합니다. 초과체류가 생겼다고 해서 모든 사례가 같은 금액과 절차로 끝난다고 가정하면 안 됩니다. 이동제한, 검문, 항공 일정 변경 같은 상황에서는 소문을 전달하기 전에 게시기관과 날짜를 확인하고 가족에게 행동지침만 짧게 보냅니다. 이 계획은 불안을 키우기 위한 목록이 아니라 평소에는 잊고 지내도 사건이 생겼을 때 누구에게 무엇을 말할지 정해 두는 생활 도구입니다.</p></section>',
	);
	$extras = array(
		'yangon-ybs-bus-route-fare-guide' => '<p>기록표에는 버스를 포기한 이유도 남깁니다. 단순 지각 우려인지, 장시간 미도착인지, 육안으로 확인한 차량 이상인지 구분하면 과장 없이 다음 통근 결정을 개선할 수 있습니다.</p>',
		'inno-city-yangon-water-bill' => '<p>월별 비교표에는 사용량, 적용 단가, 고정비, 최종 납부액을 각각 나눠 적습니다. 그래야 단가 인상과 생활습관 변화, 계량 오류 가능성을 한꺼번에 섞지 않고 관리사무소에 정확히 질문할 수 있습니다.</p>',
		'myanmar-form-c-condo-registration' => '<p>접수증에는 여권 영문명, 여권번호, 주소와 신고일이 맞는지 받은 날 확인합니다. 오타를 발견하면 그대로 보관하지 말고 담당자에게 정정 방법과 완료 예정일을 문서로 다시 묻습니다.</p>',
		'yangon-apartment-bcc-building-permit' => '<p>계약 전 검토비가 아깝게 보여도 매매대금과 향후 손실 가능성에 비하면 위험을 확인하는 비용입니다. 중개인과 이해관계가 없는 현지 전문가를 매수인이 직접 선택하는 편이 검토의 독립성을 지키기 쉽습니다.</p>',
		'yangon-dengue-monsoon-family-checklist' => '<p>발열이 가라앉은 뒤에도 상태가 나빠질 수 있다는 의료 안내를 기억하고, 스스로 완치 시점을 정하지 않습니다. 병원에 갈 때에는 여행력, 모기 노출 가능성, 복용약과 알레르기 정보를 함께 전달합니다.</p>',
		'yangon-diarrhea-cholera-food-water-safety' => '<p>회복 뒤에는 문제가 없었던 메뉴부터 소량씩 돌아가며 몸 상태를 관찰합니다. 자주 반복된다면 단순히 양곤 음식이 안 맞는다고 넘기지 말고 의료진과 상의해 다른 원인도 확인합니다.</p>',
		'myanmar-mobile-payment-cash-security' => '<p>앱 업데이트는 문자나 메신저 링크가 아니라 공식 앱스토어에서 확인합니다. 공용 와이파이에서는 큰 금액 송금을 피하고, 거래가 끝난 뒤 로그아웃 여부와 잠금화면 알림에 개인정보가 보이는지도 점검합니다.</p>',
		'myanmar-korean-resident-safety-plan' => '<p>비상가방의 현금은 소액권으로 나누고 정기적으로 상태를 확인합니다. 중요한 번호는 휴대전화뿐 아니라 종이에도 적되, 여권번호와 계정 비밀번호 같은 민감정보는 연락망과 함께 노출하지 않습니다.</p>',
	);
	return ( $notes[ $slug ] ?? '' ) . ( $extras[ $slug ] ?? '' );
}

function livingtmw_september_living_guides(): array {
	return array(
		array(
			'date'=>'2026-08-31 09:00:00','slug'=>'yangon-ybs-bus-route-fare-guide',
			'title'=>'양곤 YBS 버스 이용 전 확인할 것: 갑작스러운 노선 변경과 지각 대비',
			'excerpt'=>'YBS 이용 직원에게 들은 노선 소멸과 지각 사례, 직접 본 노후 버스 상태를 바탕으로 출퇴근 대안을 정리했습니다.',
			'content'=>livingtmw_september_guide_image('yangon-ybs-bus-guide.png','우기 아침 양곤의 노후 시내버스와 정류장을 표현한 설명 이미지').<<<'HTML'
<p class="livingtmw-field-badge">직원 이용 경험과 2026년 8월 교통 보도를 함께 확인한 가이드</p>
<p>운영자는 YBS를 직접 타본 적은 없습니다. 대신 회사 직원들이 매일 버스로 출퇴근하며 겪는 일을 들었고, 도로에서 노후 버스가 멈춰 서 있거나 엔진 부분이 드러난 듯한 상태로 운행되는 모습도 간혹 봤습니다. 직원들이 가장 곤란해한 문제는 요금보다 예고 없는 노선 변화였습니다. 어제까지 오던 노선이 다음 날 보이지 않고 공지도 찾기 어려워 다른 버스를 기다리다 지각했다는 이야기가 있었습니다.</p>
<p>모든 YBS 노선이 항상 불안정하다는 뜻은 아닙니다. 직원이 이용한 시기와 구간의 사례입니다. 다만 버스를 유일한 통근수단으로 삼으려면 지도 경로 하나만 저장하기보다 실제 운행을 확인하고 대체수단을 준비할 이유는 충분합니다.</p>
<h2>9월 요금 인상 계획은 철회됐습니다</h2>
<p>AD Shofar는 양곤지역 교통위원회가 2026년 9월 1일부터 예정했던 요금 인상을 8월 16일 철회했다고 보도했습니다. 당초 시내는 200짯에서 300짯, 외곽·교외는 400짯에서 600짯으로 조정될 예정이었지만 발표 이틀 만에 취소됐습니다. 9월부터 무조건 오른다는 오래된 안내를 믿지 말고 이후 변동은 탑승 현장에서 다시 확인하세요.</p>
<p>보도에는 등록 차량 5,399대 가운데 수리 중이거나 운행하지 못하는 차량이 적지 않다는 내용도 있습니다. 운영자가 멈춘 버스를 본 경험과 직원들의 배차 문제를 이해하는 데 도움이 됩니다. 특정 차량의 안전성을 외관만으로 단정할 수 없지만 문이 닫히지 않거나 연기, 타는 냄새, 심한 기계음이 느껴지면 타지 않는 편이 좋습니다.</p>
<h2>첫 출근 전에 같은 시간대로 시험합니다</h2>
<p>평일 아침 실제 출발 시간에 정류장으로 가서 표지, 탑승 위치, 대기시간, 환승지점과 회사까지 걷는 시간을 기록합니다. 퇴근길은 반대편 정류장이 예상과 다를 수 있으므로 별도로 시험합니다. 지도에 노선이 보여도 최근 운행을 뜻한다고 단정하지 말고 경비원, 동료와 실제 이용자에게 교차 확인합니다.</p>
<div class="livingtmw-checklist"><h3>출근 전날 확인표</h3><ul><li>주 노선과 같은 방향의 대체 노선</li><li>정류장까지 침수와 공사 여부</li><li>현금·교통카드 결제 가능 여부</li><li>택시를 안전하게 부를 위치</li><li>지연 연락을 받을 회사 담당자</li><li>충전된 전화와 오프라인 회사 주소</li></ul></div>
<h2>기다리는 상한을 정합니다</h2>
<p>언젠가 오겠지 하고 기다리면 대체 차량을 잡을 시간도 놓칩니다. 며칠간 평소 배차를 기록한 뒤 평균보다 몇 분 더 기다리면 다른 수단으로 바꾼다는 기준을 정하세요. 직원끼리 아침 운행 상황을 공유하면 같은 실패를 반복하지 않을 수 있습니다. 월 교통비에는 택시나 합승 차량을 몇 차례 이용할 비용도 포함합니다.</p>
<h2>차량 상태가 불안하면 타지 않습니다</h2>
<p>운영자가 본 버스의 정확한 구조와 정비 상태를 검사한 것은 아니므로 불법 차량이라고 단정하지 않습니다. 다만 바닥·계단이 파손됐거나 문이 닫히지 않고 누출과 과도한 연기가 보인다면 무리할 필요가 없습니다. 주행 중 이상이 생기면 안내에 따라 안전한 곳에서 내리고 차도 안쪽으로 걷지 않습니다.</p>
<h2>일주일 기록으로 판단합니다</h2>
<p>YBS는 비용을 낮추고 정해진 생활권을 반복 이동할 때 장점이 있습니다. 정시 출근이 중요하거나 아이와 큰 짐을 동반하고 야간 귀가가 잦다면 버스만으로 일정 짜기가 어렵습니다. 일주일간 출발·도착·대기·환승시간과 대체 교통비를 남겨 자신의 노선이 지속 가능한지 판단하세요.</p>
<h2>자주 묻는 질문</h2><h3>9월부터 올랐나요?</h3><p>확인한 보도에서는 인상이 철회됐습니다. 현재 금액은 다시 확인해야 합니다.</p><h3>지도 앱만 믿어도 되나요?</h3><p>직원 사례처럼 실제 운행이 다를 수 있어 같은 시간대에 시험하는 편이 안전합니다.</p>
HTML
			.livingtmw_september_depth('yangon-ybs-bus-route-fare-guide').livingtmw_september_evidence_footer('운영자는 직접 타지 않았으며 직원에게 들은 사례와 도로에서 본 상태를 구분했습니다.',array('AD Shofar YBS 요금 인상 철회'=>'https://news.myantrade.com/archives/49660'))),
		array(
			'date'=>'2026-09-01 09:00:00','slug'=>'inno-city-yangon-water-bill',
			'title'=>'양곤 Inno City 수도요금 계산: 7월 12.2톤 사용과 톤당 1,800짯',
			'excerpt'=>'Inno City에서 실제 적용받은 톤당 1,800짯과 7월 사용량 12.2톤을 공개하고 YCDC 보도와 다른 이유를 확인합니다.',
			'content'=>livingtmw_september_guide_image('yangon-water-bill-guide.png','양곤 아파트 수도 미터와 사용량 기록 설명 이미지').<<<'HTML'
<p class="livingtmw-field-badge">2026년 7월 · Inno City 거주자의 실제 사용량</p>
<p>Inno City에서는 수도요금을 물 1톤당 1,800짯으로 계산합니다. 2026년 7월 운영자 집 사용량은 12.2톤이었습니다. 단순 사용분은 12.2×1,800으로 21,960짯입니다. 양곤 전체 평균이나 YCDC가 모든 외국인에게 청구하는 표준액이 아니라 운영자가 실제 확인한 사례입니다.</p>
<p>콘도 청구서에는 물 공급방식, 공용 설비, 펌프·탱크 관리와 자체 부과 기준이 반영될 수 있습니다. YCDC 단가와 다르다고 곧바로 과다청구라고 할 수 없습니다. 단위가 톤인지 유닛인지, 검침값과 사용량이 맞는지, 물값 외에 무엇이 포함됐는지부터 확인합니다.</p>
<h2>실제 계산을 공개합니다</h2>
<div class="livingtmw-table-wrap"><table><thead><tr><th>항목</th><th>실제 기록</th><th>확인할 점</th></tr></thead><tbody><tr><td>월</td><td>2026년 7월</td><td>검침 시작·종료일</td></tr><tr><td>사용량</td><td>12.2톤</td><td>미터값 차이</td></tr><tr><td>단가</td><td>1,800짯/톤</td><td>포함 항목</td></tr><tr><td>단순액</td><td>21,960짯</td><td>기본료가 있으면 변동</td></tr></tbody></table></div>
<p>최종액이 다르면 이전 달 미납, 공용 수도, 미터 관리비, 세금, 반올림과 검침기간 차이를 찾습니다. 설명이 없다면 청구서를 촬영해 항목별 산식을 요청하세요. 답변을 메시지로 남기면 다음 달 비교가 쉽습니다.</p>
<h2>YCDC 보도와 바로 비교하지 않습니다</h2>
<p>AD Shofar는 외국인 가정용 기본료를 1유닛당 880짯, 월 30유닛 초과 1,100짯, 60유닛 초과 1,320짯으로 소개했습니다. 미터가 고장·분실됐거나 없으면 기본 사용량의 6배를 기준으로 부과할 수 있다는 내용도 있습니다.</p>
<p>이를 Inno City의 1,800짯과 비교하려면 유닛 정의, YCDC 직결 여부, 지하수·탱크·펌프 사용, 관리비 포함 여부를 알아야 합니다. 다른 공급구조의 숫자를 단가만 보고 비교하면 잘못된 결론이 됩니다.</p>
<h2>입주 첫날 미터를 찍습니다</h2>
<p>세대 미터가 있다면 입주일 검침값을 계약서에 적고 집주인과 같은 사진을 공유합니다. 이전 거주자 사용량이 섞이는 일을 막기 위해서입니다. 잠긴 설비실에 있다면 매달 검침사진을 받을 수 있는지 문의합니다. 세대 미터 없이 인원수나 면적으로 나누면 계산기준과 빈집 부담방식을 서면으로 확인합니다.</p>
<div class="livingtmw-checklist"><h3>매달 기록</h3><ul><li>이전값과 현재값 사진</li><li>사용량·단가·최종금액</li><li>가족 수와 외출기간</li><li>누수수리·물탱크 청소</li><li>공용료와 세대료 구분</li><li>관리실 답변</li></ul></div>
<h2>갑자기 늘면 누수를 봅니다</h2>
<p>수도꼭지와 세탁기, 정수기 급수를 끈 뒤 미터가 움직이는지 봅니다. 변기, 싱크대 하부, 온수기와 정수기 호스를 확인합니다. 벽 안 누수나 전기설비 근처 젖음은 직접 뜯지 말고 관리실에 요청합니다.</p>
<h2>비용과 음용 안전은 별개입니다</h2>
<p>비용을 줄이려고 손 씻기와 음식 세척을 줄이면 안 됩니다. 누수를 빨리 고치고 샤워시간과 세탁횟수를 조절합니다. 수돗물을 마실 수 있는지는 별도 문제입니다. 탱크·배관·정수기 관리를 확인하고 냄새와 색이 달라지면 마시지 않습니다.</p>
<h2>세 달을 비교합니다</h2>
<p>12.2톤이 많고 적은지는 가족 수와 검침기간 없이 단정할 수 없습니다. 최소 세 달을 같은 날짜에 기록해 자기 집의 평소 범위를 만드세요. 손님, 여행, 누수와 대청소를 메모하면 변동을 설명하기 쉽습니다.</p>
<h2>자주 묻는 질문</h2><h3>모든 세대가 1,800짯인가요?</h3><p>운영자 세대 사례입니다. 본인 청구서를 확인하세요.</p><h3>최종액이 다르면요?</h3><p>검침기간, 미터값, 공용료와 미납액을 먼저 대조하세요.</p>
