function livingtmw_publish_overdue_september_guides(): void {
	foreach ( livingtmw_september_living_guides() as $entry ) {
		$due_at = DateTimeImmutable::createFromFormat( 'Y-m-d H:i:s', $entry['date'], wp_timezone() );
		if ( false === $due_at || $due_at > current_datetime() ) {
			continue;
		}
		$post = get_page_by_path( $entry['slug'], OBJECT, 'post' );
		if ( $post instanceof WP_Post && 'future' === $post->post_status ) {
			wp_publish_post( $post->ID );
		}
	}
}

function livingtmw_seed_september_living_guides(): void {
	livingtmw_publish_overdue_september_guides();
	$revision = '2026-08-29-september-original-guides-v2';
	if ( $revision === get_option( 'livingtmw_september_guides_revision' ) ) {
		return;
	}
	$category = get_term_by( 'slug', 'yangon-korean-local-services', 'category' );
	$category_id = $category instanceof WP_Term ? (int) $category->term_id : (int) get_option( 'default_category' );
	$all_saved = true;
	foreach ( livingtmw_september_living_guides() as $entry ) {
		$existing = get_page_by_path( $entry['slug'], OBJECT, 'post' );
		$postarr = array(
			'post_title' => $entry['title'], 'post_name' => $entry['slug'], 'post_excerpt' => $entry['excerpt'],
			'post_content' => $entry['content'], 'post_status' => strtotime( $entry['date'] ) <= current_time( 'timestamp' ) ? 'publish' : 'future',
			'post_date' => $entry['date'], 'post_date_gmt' => get_gmt_from_date( $entry['date'] ), 'post_type' => 'post',
			'post_author' => 1, 'post_category' => $category_id > 0 ? array( $category_id ) : array(),
			'comment_status' => 'closed', 'ping_status' => 'closed',
		);
		if ( $existing instanceof WP_Post ) { $postarr['ID'] = $existing->ID; }
		if ( is_wp_error( wp_insert_post( wp_slash( $postarr ), true ) ) ) { $all_saved = false; }
	}
	if ( $all_saved ) { update_option( 'livingtmw_september_guides_revision', $revision, false ); }
}
add_action( 'init', 'livingtmw_seed_september_living_guides', 36 );
